package com.madhukar.upisplitter.controller;
import com.madhukar.upisplitter.dto.*; import com.madhukar.upisplitter.dto.PaymentDtos.*; import com.madhukar.upisplitter.model.PaymentTransaction.Status; import com.madhukar.upisplitter.service.PaymentPlanService; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/payment-plans") public class PaymentPlanController {private final PaymentPlanService service;public PaymentPlanController(PaymentPlanService s){service=s;}private String uid(Authentication a){return (String)a.getDetails();}@PostMapping public ApiDtos.ApiResponse<PlanResponse> create(@Valid @RequestBody CreatePlanRequest r,Authentication a){return ApiResponseFactory.ok("Payment plan created",service.create(uid(a),r));}@GetMapping public ApiDtos.ApiResponse<List<PlanResponse>> list(Authentication a){return ApiResponseFactory.ok("Payment plans loaded",service.list(uid(a)));}@GetMapping("/{id}") public ApiDtos.ApiResponse<PlanResponse> get(@PathVariable String id,Authentication a){return ApiResponseFactory.ok("Payment plan loaded",service.get(uid(a),id));}@DeleteMapping("/{id}") public ApiDtos.ApiResponse<Void> delete(@PathVariable String id,Authentication a){service.delete(uid(a),id);return ApiResponseFactory.ok("Payment plan deleted",null);}@PatchMapping("/payments/{id}/simulate-success") public ApiDtos.ApiResponse<StatusResponse> success(@PathVariable String id,Authentication a){return ApiResponseFactory.ok("Payment updated",service.changeStatus(uid(a),id,Status.SUCCESS));}@PatchMapping("/payments/{id}/simulate-failure") public ApiDtos.ApiResponse<StatusResponse> failure(@PathVariable String id,Authentication a){return ApiResponseFactory.ok("Payment updated",service.changeStatus(uid(a),id,Status.FAILED));}}
